def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(s):
        if not s or not s.isascii() or not s.isdigit():
            return None

        # Small chunks avoid Python's limit on decimal-string conversion.
        value = 0
        for start in range(0, len(s), 9):
            chunk = s[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split()
        if not parts or len(parts) != arities.get(parts[0], 0):
            rejected.append(index)
            continue

        verb = parts[0]

        if verb == "undo":
            if not history:
                rejected.append(index)
            else:
                for name, previous in history.pop():
                    if previous is None:
                        del accounts[name]
                    else:
                        accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]
        state = accounts.get(name)
        updates = None

        if verb == "open":
            if state is None:
                updates = {name: (amount, False)}

        elif verb == "deposit":
            if state is not None:
                balance, frozen = state
                updates = {name: (balance + amount, frozen)}

        elif verb == "withdraw":
            if state is not None:
                balance, frozen = state
                if not frozen and balance >= amount:
                    updates = {name: (balance - amount, frozen)}

        elif verb == "transfer":
            destination = parts[2]
            destination_state = accounts.get(destination)
            if name != destination and state is not None and destination_state is not None:
                balance, frozen = state
                if not frozen and balance >= amount:
                    destination_balance, destination_frozen = destination_state
                    updates = {
                        name: (balance - amount, frozen),
                        destination: (
                            destination_balance + amount,
                            destination_frozen,
                        ),
                    }

        elif verb == "freeze":
            if state is not None and not state[1]:
                updates = {name: (state[0], True)}

        elif verb == "unfreeze":
            if state is not None and state[1]:
                updates = {name: (state[0], False)}

        if updates is None:
            rejected.append(index)
        else:
            history.append(
                tuple((account, accounts.get(account)) for account in updates)
            )
            accounts.update(updates)

    return {name: state[0] for name, state in accounts.items()}, rejected
